import test from 'node:test';
import assert from 'node:assert/strict';
import {correctProductData} from './product-title-corrections.mjs';
const rows=[{id:'88kDU9mSlJdWzZPx4bim',titulo:'Creatina 1kg Suplemento Monohidratada em pó 100% Pura - Soldiers Nutrition',listing:'MLB2766771378'},{id:'8oHSkf32jY7LKS2WSv36',titulo:'Câmera Segurança Ip Externa Wifi A28 App Icsee À Prova Dágua',listing:'MLB4188994271'}];
test('triagem59 exige ID título e anúncio, conserva operação e é idempotente',()=>{for(const r of rows){const p={...r,preco:'salvo',historico:'preservado',linkAfiliado:'https://meli.la/preservar',variation_id:'123'},x=correctProductData(p);for(const k of Object.keys(p).filter(k=>k!=='titulo'))assert.deepEqual(x[k],p[k]);assert.deepEqual(correctProductData(x),x);for(const alt of [{id:'outro'},{titulo:'Capa para '+r.titulo},{link:'https://www.mercadolivre.com.br/p/MLB12345678?wid=MLB9999999999'}])assert.equal(correctProductData({...p,comentario:'preservar',...alt}).comentario,'preservar');assert.ok(x.titulo.length<=100);}});
test('Soldiers não transforma tamanho em dose ou título em teste de pureza',()=>{const x=correctProductData(rows[0]);assert.doesNotMatch(x.titulo,/100%/);assert.match(x.comentario,/Não verificamos a composição ou a pureza deste lote/);assert.match(x.comentario,/não recomenda dose/);assert.doesNotMatch(x.pros,/pura|força|resistência|segura|aprovad/i);assert.ok(!x.comentario.endsWith('…'));});
test('A28 explicita modelo divergente sem transferir especificações da A28B',()=>{const x=correctProductData(rows[1]);assert.match(x.comentario,/comprove equivalência entre A28 e A28B/);assert.match(x.comentario,/permanecem sem confirmação/);assert.doesNotMatch(x.pros,/6 MP|64|ONVIF|NVR|prova de água|360/i);});
